-- Frost Mage rework: Talent Tree Step 3, Cluster C batch 1
-- (Permafrost, Frozen Core, Improved Cone of Cold, Enduring Winter, Shattered Barrier,
-- Empowering Frostbolt) -- see docs/frost-mage-talent-tree-content-handoff.md
DELETE FROM `spell_dbc` WHERE `ID` IN (11175, 12569, 12571, 31667, 31668, 31669, 11190, 12489, 12490, 44557, 44560, 44561, 44745, 54787, 31682, 31683, 200015, 200016, 200017, 200018, 200019, 200020, 200021, 200022, 200023, 200024);

-- spell_bonus_data: Frozen Core's capstone DoT (200019). SCHOOL_ABSORB/other non-damage effect
-- types don't consult this table at all (see the Ice Barrier comment above) but PERIODIC_DAMAGE
-- does, via AuraEffect::CalculateAmount's periodic-damage case -> Unit::SpellDamageBonusDone.
-- Modest first-pass tuning value, same idiom as this project's other new proc-only spells
-- (Icy Bite, Icy Shatter).
DELETE FROM `spell_bonus_data` WHERE `entry` IN (200019);

-- Script bindings for this pass's new/extended classes (spell_mage.cpp).
DELETE FROM `spell_script_names` WHERE (`spell_id`, `ScriptName`) IN ((12571, 'spell_mage_permafrost'), (30455, 'spell_mage_ice_lance'), (6136, 'spell_mage_chilled'), (7321, 'spell_mage_chilled'), (31669, 'spell_mage_frozen_core'), (44561, 'spell_mage_enduring_winter'));
